args.command:
python3 - <<'PY'
import os,re
roots=['server','store','internal','cmd']
pat=re.compile(r'Visibility|PRIVATE|PROTECTED|PUBLIC|canViewMemo|creator|share|SSE|RSS|fileserver',re.I)
for root in roots:
 for dp,dn,fns in os.walk(root):
  dn[:]=[d for d in dn if d not in {'.git','node_modules'}]
  for fn in fns:
   if not fn.endswith('.go') or fn.endswith('_test.go'): continue
   p=os.path.join(dp,fn)
   try: lines=open(p,encoding='utf-8').read().splitlines()
   except: continue
   hits=[(i+1,s.strip()) for i,s in enumerate(lines) if pat.search(s)]
   if hits:
    print('\n'+p)
    for i,s in hits: print(f'{i}:{s}')
PY

