// serveAttachmentFile serves attachment binary content using native HTTP.
func (s *FileServerService) serveAttachmentFile(c *echo.Context) error {
	ctx := c.Request().Context()
	uid := c.Param("uid")
	wantThumbnail := c.QueryParam("thumbnail") == "true"
	wantMotion := c.QueryParam("motion") == "true"

	attachment, err := s.Store.GetAttachment(ctx, &store.FindAttachment{
		UID:     &uid,
		GetBlob: true,
	})
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get attachment").Wrap(err)
	}
	if attachment == nil {
		return echo.NewHTTPError(http.StatusNotFound, "attachment not found")
	}

	if err := s.checkAttachmentPermission(ctx, c, attachment); err != nil {
		return err
	}

	if wantMotion {
		return s.serveMotionClip(c, attachment)
	}

	contentType := s.sanitizeContentType(attachment.Type)

	// Stream video/audio to avoid loading entire file into memory.
	if isMediaType(attachment.Type) {
		return s.serveMediaStream(c, attachment, contentType)
	}

	return s.serveStaticFile(c, attachment, contentType, wantThumbnail)
}

// serveUserAvatar serves user avatar images.
func (s *FileServerService) serveUserAvatar(c *echo.Context) error {
	ctx := c.Request().Context()

	// On a private instance (no InstanceURL), avatars are not exposed to anonymous
	// visitors; a valid session, access token, or PAT is required.
	if !s.Profile.AllowAnonymous() {
		viewer, err := s.getCurrentUser(ctx, c)
		if err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to get current user").Wrap(err)
		}
		if viewer == nil {
			return echo.NewHTTPError(http.StatusUnauthorized, "unauthorized access")
		}
	}

	identifier := c.Param("identifier")

	user, err := s.getUserByUsername(ctx, identifier)
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get user").Wrap(err)
	}
	if user == nil {
		return echo.NewHTTPError(http.StatusNotFound, "user not found")
	}
	if user.AvatarURL == "" {
		return echo.NewHTTPError(http.StatusNotFound, "avatar not found")
	}

	imageType, imageData, err := s.parseDataURI(user.AvatarURL)
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to parse avatar data").Wrap(err)
	}

	if !avatarAllowedTypes[imageType] {
		return echo.NewHTTPError(http.StatusBadRequest, "invalid avatar image type")
	}

	setSecurityHeaders(c)
	c.Response().Header().Set(echo.HeaderContentType, imageType)
	c.Response().Header().Set(echo.HeaderCacheControl, cacheMaxAge)

	return c.Blob(http.StatusOK, imageType, imageData)

import { ROUTES } from "@/router/routes";

/** Query parameter used to preserve the intended destination across the auth flow. */
export const AUTH_REDIRECT_PARAM = "redirect";

/** Query parameter used to surface why the user was sent to the auth page. */
export const AUTH_REASON_PARAM = "reason";

/** Reason code signalling that the user hit a memo that requires authentication. */
export const AUTH_REASON_PROTECTED_MEMO = "protected-memo";

/**
 * Validates a post-authentication redirect target.
 *
 * Returns the path when it is a safe same-origin internal destination, otherwise `undefined`.
 * Rejected targets include: non-string / empty, protocol-relative URLs (`//host`), absolute URLs,
 * and any auth-family route (`/auth`, `/auth/callback`, …) which must not be a landing target
 * after sign-in.
 */
export function getSafeRedirectPath(path: string | null | undefined): string | undefined {
  if (!path) {
    return undefined;
  }

  if (!path.startsWith("/") || path.startsWith("//")) {
    return undefined;
  }

  // Never let a redirect target point back into the auth flow — it would either
  // bounce the user in a guest/auth guard loop or hijack the OAuth callback.
  if (path === ROUTES.AUTH || path.startsWith(`${ROUTES.AUTH}/`) || path.startsWith(`${ROUTES.AUTH}?`)) {
    return undefined;
  }

  return path;
}

/**
 * Builds a URL pointing at the auth entry page, optionally embedding a validated
 * `redirect` target and a machine-readable `reason` code.
 */
export function buildAuthRoute(options?: { redirect?: string | null; reason?: string | null }): string {
  const searchParams = new URLSearchParams();
  const redirectPath = getSafeRedirectPath(options?.redirect);

  if (redirectPath) {
    searchParams.set(AUTH_REDIRECT_PARAM, redirectPath);
  }

  if (options?.reason) {
    searchParams.set(AUTH_REASON_PARAM, options.reason);
  }

  const search = searchParams.toString();
  return search ? `${ROUTES.AUTH}?${search}` : ROUTES.AUTH;
}

const PUBLIC_ROUTE_PREFIXES = [
  ROUTES.AUTH, // Authentication pages
  ROUTES.ABOUT, // About page
  ROUTES.EXPLORE, // Explore page
  `${ROUTES.SHARED_MEMO}/`, // Shared memo pages (share-link viewer)
  "/u/", // User profile pages (dynamic)
  "/memos/", // Individual memo detail pages (dynamic)
] as const;

/**
 * Reports whether a given pathname corresponds to a page that unauthenticated
 * visitors are allowed to view without being bounced to the auth page.
 */
export function isPublicRoute(path: string): boolean {
  return PUBLIC_ROUTE_PREFIXES.some((route) => path.startsWith(route));
}

/**
 * Reports whether an anonymous visitor to a private instance should be redirected
 * to the sign-in page for the given path.
 *
 * A private instance (no configured instance URL) hides everything from anonymous
 * visitors except share-link pages, which stay accessible so public shares keep
 * working. Authenticated visitors and open instances are never gated.
 */
export function shouldGatePrivateInstance(params: { isPrivateInstance: boolean; isAuthenticated: boolean; pathname: string }): boolean {
  const { isPrivateInstance, isAuthenticated, pathname } = params;
  if (!isPrivateInstance || isAuthenticated) {
    return false;
  }
  return !pathname.startsWith(`${ROUTES.SHARED_MEMO}/`);
}

/**
 * Appends the given search params to a path, so links between auth pages
 * (sign-in <-> sign-up) preserve the redirect target and other params.
 */
export function appendSearchParams(path: string, searchParams: URLSearchParams): string {
  const queryString = searchParams.toString();
  return queryString ? `${path}?${queryString}` : path;
}

import { Navigate, Outlet, useLocation, useSearchParams } from "react-router-dom";
import useCurrentUser from "@/hooks/useCurrentUser";
import { AUTH_REDIRECT_PARAM, buildAuthRoute, getSafeRedirectPath } from "@/utils/auth-redirect";
import { ROUTES } from "./routes";

/**
 * Index-route gate mounted at `/`. Authenticated visitors fall through to the
 * nested Home page; unauthenticated visitors are redirected to `/explore`,
 * preserving the original query string and hash so bookmarks like `/?filter=foo`
 * keep working.
 */
export const LandingRoute = () => {
  const currentUser = useCurrentUser();
  const location = useLocation();

  if (!currentUser) {
    return (
      <Navigate
        to={{
          pathname: ROUTES.EXPLORE,
          search: location.search,
          hash: location.hash,
        }}
        replace
      />
    );
  }

  return <Outlet />;
};

/**
 * Guard for routes that require an authenticated user. Unauthenticated visitors
 * are redirected to `/auth` with the original location preserved as the `redirect`
 * query parameter, so they return to the intended page after signing in.
 */
export const RequireAuthRoute = () => {
  const currentUser = useCurrentUser();
  const location = useLocation();

  if (!currentUser) {
    const redirect = `${location.pathname}${location.search}${location.hash}`;
    return <Navigate to={buildAuthRoute({ redirect })} replace />;
  }

  return <Outlet />;
};

/**
 * Guard for guest-only routes (sign-in and sign-up). Already-authenticated users
 * are redirected to the requested `redirect` target (when safe) or to `/`.
 *
 * The OAuth callback route (`/auth/callback`) intentionally opts out of this guard:
 * an authenticated session in another tab must not prevent the callback from
 * consuming its one-time OAuth state and completing the in-flight sign-in.
 */
export const RequireGuestRoute = () => {
  const currentUser = useCurrentUser();
  const [searchParams] = useSearchParams();

  if (currentUser) {
    const redirectTarget = getSafeRedirectPath(searchParams.get(AUTH_REDIRECT_PARAM));
    return <Navigate to={redirectTarget || ROUTES.HOME} replace />;
  }

  return <Outlet />;
};

